mapper.select:
select pm.project_member_no as projectMemberNo, pm.emp_no as empNo, e.emp_name as memberName, e.emp_dept_no as deptName, e.emp_position_no as jobPosition from project_member pm inner join emp e on pm.emp_no = e.emp_no where pm.project_no = #{projectNo}
and ( pm.project_member_no != nvl(( select assigned_member_no from task where task_no = #{taskNo} ), -1) )
and pm.project_member_no not in ( select nvl(project_member_no, -1) from task_collaborator where task_no = #{taskNo} ) order by e.emp_name asc

mapper.delete:
delete from task_collaborator
where task_no = #{taskNo}
  and project_member_no = #{projectMemberNo}
